// closings -----------------------------------------------------------------------

/**
 * live/closings.json: every school closed, delayed, remote or dismissing early for weather.
 *
 * One group per local day, in date order; each school has a row on at most two
 * of them, its local today and tomorrow. A school with no row has no weather
 * status on file; whether it is open is known only where live/covered.json says so.
 */
export interface ClosingsFile {
  readonly schema_version: SchemaVersion;
  readonly generated_at: UtcInstant;
  readonly directory: DirectoryStamp;
  /**
   * The local days with a status, sorted. Each is today or tomorrow somewhere in the contiguous US
   * at generated_at: two dates, or three between 04:00 and 08:00 UTC.
   */
  readonly days: readonly ClosingsDay[];
}

/**
 * Every school with a weather status on one local day, as parallel columns.
 *
 * Row i is gaps[i], statuses[i], announced[i] and reasons[i]; rows are in school
 * order. shifts and clocks hold one entry for each delayed or early-dismissal
 * row, in row order: the k-th entry belongs to the k-th such row.
 */
export interface ClosingsDay {
  readonly day: LocalDate;
  /** Each row's school, as a gap from the previous row's. */
  readonly gaps: readonly SchoolGap[];
  /** Each row's status. */
  readonly statuses: readonly Status[];
  /**
   * When each row's status was first posted, in minutes before generated_at; null when the listing
   * gave no time.
   */
  readonly announced: readonly (MinutesAgo | null)[];
  /** The weather each row names; null when none was named. */
  readonly reasons: readonly (Reason | null)[];
  /**
   * For each delayed or early-dismissal row, how late the day starts or how early it ends; null
   * unless the listing states it.
   */
  readonly shifts: readonly (ShiftMinutes | null)[];
  /**
   * For each delayed or early-dismissal row, the stated opening or dismissal time; null unless the
   * listing states it.
   */
  readonly clocks: readonly (MinuteOfDay | null)[];
}

/**
 * A local wall-clock time as minutes after midnight (630 is 10:30).
 * @minimum 0
 * @exclusiveMaximum 1440
 */
export type MinuteOfDay = number;

/**
 * Whole minutes before the minute of generated_at: the moment is the start of the UTC minute that
 * many minutes earlier, and 0 is generated_at's own minute.
 * @minimum 0
 * @maximum 20160
 */
export type MinutesAgo = number;

/**
 * A school index written as its distance from the one before it: index = previous index + 1 + gap,
 * and the first previous index is -1. So [4, 0, 2] is schools 4, 5 and 8.
 * @minimum 0
 * @maximum 4294967294
 */
export type SchoolGap = number;

/**
 * A length of time in whole minutes.
 * @minimum 1
 * @maximum 720
 */
export type ShiftMinutes = number;

