// school-directory ---------------------------------------------------------------

/**
 * schools/meta.json: every school on the map, in points.bin order.
 *
 * Public schools come first, sorted by id, then private schools sorted by id.
 */
export interface SchoolDirectoryMeta {
  readonly schema_version: SchemaVersion;
  readonly generated_on: LocalDate;
  readonly count: Count;
  readonly ids: readonly SchoolId[];
  readonly names: readonly DirectoryName[];
  readonly districts: DistrictList;
  readonly school_years: SchoolYears;
}

/**
 * A school's or district's name as the directory spells it.
 * @minLength 1
 * @maxLength 200
 */
export type DirectoryName = string;

/**
 * A school district's 7-digit federal id.
 * @pattern ^\d{7}$
 */
export type DistrictId = string;

/** Every district with a school on the map, sorted by id. */
export interface DistrictList {
  readonly ids: readonly DistrictId[];
  readonly names: readonly DirectoryName[];
}

/**
 * A school's federal id: 12 digits for a public school, 8 letters or digits for a private one.
 * @pattern ^(?:\d{12}|[0-9A-Z]{8})$
 */
export type SchoolId = string;

/** The school year of the directory each kind of school comes from. */
export interface SchoolYears {
  readonly public: SchoolYear;
  readonly private: SchoolYear;
}

// season-stats -------------------------------------------------------------------

/**
 * stats/season.json: this school year's weather closures so far.
 *
 * days lists every local day with at least one affected school, in order; states
 * sums the same school-days by state, so both add up to the same totals.
 */
export interface SeasonStats {
  readonly schema_version: SchemaVersion;
  readonly generated_at: UtcInstant;
  readonly season: SchoolYear;
  /** The last local day counted. */
  readonly through: LocalDate;
  readonly days: readonly DayCounts[];
  readonly states: readonly StateCounts[];
  /** Distinct schools with any status this season. */
  readonly schools: Count;
  /** Distinct districts with an affected school. */
  readonly districts: Count;
}

/**
 * Schools with each status on one local day.
 * @minItems 5
 * @maxItems 5
 */
export type DayCounts = readonly [
  day: LocalDate,
  closed: Count,
  delayed: Count,
  remote: Count,
  early_dismissal: Count,
];

/**
 * School-days with each status in one state, over the season so far.
 * @minItems 5
 * @maxItems 5
 */
export type StateCounts = readonly [
  state: Usps,
  closed: Count,
  delayed: Count,
  remote: Count,
  early_dismissal: Count,
];

// track-record -------------------------------------------------------------------

/**
 * track-record.json: how past chances compared with what schools did.
 *
 * first_day and last_day bound the local days scored; both are null, and every
 * count is 0, until a day has been scored.
 */
export interface TrackRecord {
  readonly schema_version: SchemaVersion;
  readonly generated_at: UtcInstant;
  readonly first_day: LocalDate | null;
  readonly last_day: LocalDate | null;
  readonly leads: readonly LeadRecord[];
}

/** How often one outcome happened, grouped by the chance given for it. */
export interface Calibration {
  readonly forecasts: Count;
  readonly outcomes: Count;
  readonly bins: readonly CalibrationBin[];
}

/**
 * [low, high, forecasts, outcomes]: of the district-days given a chance from low up to (not
 * including) high percent (the last bin includes 100), how many there were and how many had the
 * outcome.
 * @minItems 4
 * @maxItems 4
 */
export type CalibrationBin = readonly [
  low: Percent,
  high: Percent,
  forecasts: Count,
  outcomes: Count,
];

/**
 * How far ahead a chance was given: 0 that morning, 1 the day before.
 * @minimum 0
 * @maximum 2
 */
export type LeadDays = number;

/** How the chances given some days ahead compared with what schools did. */
export interface LeadRecord {
  readonly lead_days: LeadDays;
  readonly no_school: Calibration;
  readonly delay: Calibration;
}
